defmodule Astraea.External.ThfPrinter do
  @moduledoc """
  Prints `Astraea.Arena` terms and clause sets as TPTP THF0: self-contained
  problems for external provers (`problem/3`) and the building blocks shared with
  the TSTP proof output of `Astraea.Tstp` (`clause/4`, `formula/4`,
  `declarations/3`).

  Each clause becomes a closed `thf(..., axiom, ...)` formula whose free variables
  are universally quantified. Base types, constants, and content-addressed Skolem
  symbols reachable from the clauses are declared up front, so the output needs no
  `include` directives. De Bruijn binders are printed as named variables `B<depth>`
  and clause variables as `V<fvar_id>`. Combinator nodes (`S, K, I, B, C`) are
  printed as their defining lambda terms.
  """

  alias Astraea.{Arena, ProofChecker}

  # Node tags (u8) matching `Astraea.Arena`
  @tag_const 1
  @tag_bvar 2
  @tag_fvar 3
  @tag_app 4
  @tag_lam 5
  @tag_eq 6
  @tag_not 7
  @tag_or 8
  @tag_forall 9
  @tag_skolem 10
  @tag_comb 11

  @comb_s 1
  @comb_k 2
  @comb_i 3
  @comb_b 4
  @comb_c 5

  @lower_word ~r/^[a-z][A-Za-z0-9_]*$/
  @dollar_word ~r/^\$\$?[a-z][A-Za-z0-9_]*$/

  @typedoc "Uninterpreted symbols (name and type) that need a type declaration."
  @type symbols :: MapSet.t({String.t(), Arena.type_id()})

  @doc """
  Renders `clauses` as a THF0 problem. Options:
    * `:role` - formula role for every clause (default `"axiom"`)
    * `:name_prefix` - prefix for formula names (default `"c"`)
  """
  @spec problem(Arena.t(), [ProofChecker.clause()], keyword()) :: String.t()
  def problem(%Arena{} = arena, clauses, opts \\ []) do
    role = Keyword.get(opts, :role, "axiom")
    prefix = Keyword.get(opts, :name_prefix, "c")

    {formulas, symbols} =
      clauses
      |> Enum.with_index()
      |> Enum.map_reduce(MapSet.new(), fn {clause, idx}, syms ->
        {body, syms} = clause(arena, clause, syms)
        {["thf(", prefix, Integer.to_string(idx), ", ", role, ", ", body, ").\n"], syms}
      end)

    IO.iodata_to_binary([
      "% Generated by Astraea.External.ThfPrinter\n",
      declarations(arena, symbols),
      formulas
    ])
  end

  @doc """
  Renders a single closed clause formula (without the `thf(...)` wrapper).
  """
  @spec clause_to_string(Arena.t(), ProofChecker.clause()) :: String.t()
  def clause_to_string(%Arena{} = arena, clause) do
    {body, _syms} = clause(arena, clause, MapSet.new())
    IO.iodata_to_binary(body)
  end

  @doc """
  Renders `clause` as a closed formula: the disjunction of its literals (`$false`
  when empty), universally quantified over its free variables. Returns the iodata
  and `syms` extended by the symbols it uses (see `declarations/3`).

  Options:
    * `:var_name` - `fn fvar_id -> iodata end` naming free variables (default
      `V<fvar_id>`); names must be TPTP variables
  """
  @spec clause(Arena.t(), ProofChecker.clause(), symbols(), keyword()) :: {iodata(), symbols()}
  def clause(%Arena{} = arena, clause, syms, opts \\ []) do
    vname = Keyword.get(opts, :var_name, &default_var_name/1)
    lits = Enum.sort(clause)

    vars =
      lits
      |> Enum.reduce(MapSet.new(), fn {_pol, atom}, acc ->
        MapSet.union(acc, Arena.free_vars(arena, atom))
      end)
      |> Enum.sort()

    {lit_strs, syms} =
      Enum.map_reduce(lits, syms, fn {pol, atom}, acc ->
        {str, acc} = term(arena, atom, 0, acc, vname)
        {if(pol == :neg, do: ["(~ ", str, ")"], else: str), acc}
      end)

    disj =
      case lit_strs do
        [] -> "$false"
        _ -> ["(", Enum.intersperse(lit_strs, " | "), ")"]
      end

    case vars do
      [] ->
        {disj, syms}

      _ ->
        binders =
          Enum.map_intersperse(vars, ", ", fn {id, ty} -> [vname.(id), ": ", type(arena, ty)] end)

        {["( ! [", binders, "]: ", disj, " )"], syms}
    end
  end

  @doc """
  Renders the term `term_id` with free variables named as in `clause/4`. Returns
  the iodata and `syms` extended by the symbols it uses.
  """
  @spec formula(Arena.t(), Arena.term_id(), symbols(), keyword()) :: {iodata(), symbols()}
  def formula(%Arena{} = arena, term_id, syms, opts \\ []) do
    term(arena, term_id, 0, syms, Keyword.get(opts, :var_name, &default_var_name/1))
  end

  @doc """
  Renders `$tType` declarations for the base types of `arena` and type
  declarations for `symbols`, named `<prefix>ty_<i>` and `<prefix>sym_<i>`.
  """
  @spec declarations(Arena.t(), symbols(), String.t()) :: iodata()
  def declarations(%Arena{} = arena, symbols, prefix \\ "") do
    [type_decls(arena, prefix), symbol_decls(arena, symbols, prefix)]
  end

  @doc """
  Renders the type `ty_id` of `arena`.
  """
  @spec type(Arena.t(), Arena.type_id()) :: iodata()
  def type(%Arena{} = arena, ty_id) do
    case Map.fetch!(arena.type_table, ty_id) do
      :o -> "$o"
      :i -> "$i"
      {:base, name} -> atom(name)
      {:arrow, dom, cod} -> ["(", type(arena, dom), " > ", type(arena, cod), ")"]
    end
  end

  @doc """
  Renders `name` as a TPTP atomic word, single-quoted unless it is a lower word or
  a `$`-word.
  """
  @spec atom(String.t()) :: String.t()
  def atom(name) do
    if Regex.match?(@lower_word, name) or Regex.match?(@dollar_word, name) do
      name
    else
      "'" <> (name |> String.replace("\\", "\\\\") |> String.replace("'", "\\'")) <> "'"
    end
  end

  defp default_var_name(id), do: ["V", Integer.to_string(id)]

  defp term(arena, id, depth, syms, vname) do
    {tag, _flags, ty, left, right} = Arena.get_node(arena, id)

    case tag do
      @tag_const ->
        name = Map.fetch!(arena.symbol_names, left)
        syms = if String.starts_with?(name, "$"), do: syms, else: MapSet.put(syms, {name, ty})
        {atom(name), syms}

      @tag_skolem ->
        name = skolem_name(left)
        {name, MapSet.put(syms, {name, ty})}

      @tag_bvar ->
        {["B", Integer.to_string(depth - 1 - left)], syms}

      @tag_fvar ->
        {vname.(left), syms}

      @tag_app ->
        {f, syms} = term(arena, left, depth, syms, vname)
        {a, syms} = term(arena, right, depth, syms, vname)
        {["(", f, " @ ", a, ")"], syms}

      @tag_lam ->
        binder(arena, "^", left, right, depth, syms, vname)

      @tag_forall ->
        binder(arena, "!", left, right, depth, syms, vname)

      @tag_eq ->
        {l, syms} = term(arena, left, depth, syms, vname)
        {r, syms} = term(arena, right, depth, syms, vname)
        {["(", l, " = ", r, ")"], syms}

      @tag_not ->
        {a, syms} = term(arena, left, depth, syms, vname)
        {["(~ ", a, ")"], syms}

      @tag_or ->
        {l, syms} = term(arena, left, depth, syms, vname)
        {r, syms} = term(arena, right, depth, syms, vname)
        {["(", l, " | ", r, ")"], syms}

      @tag_comb ->
        {combinator(arena, left, ty), syms}
    end
  end

  defp binder(arena, quant, dom, body, depth, syms, vname) do
    {b, syms} = term(arena, body, depth + 1, syms, vname)
    {["(", quant, " [B", Integer.to_string(depth), ": ", type(arena, dom), "]: ", b, ")"], syms}
  end

  # Combinators are closed terms, so the fixed binder names X, Y, Z cannot capture outer variables.
  defp combinator(arena, comb, ty) do
    case {comb, domains(arena, ty, comb_arity(comb))} do
      {@comb_i, [a]} -> ["(^ [X: ", type(arena, a), "]: X)"]
      {@comb_k, [a, b]} -> ["(^ [X: ", type(arena, a), ", Y: ", type(arena, b), "]: X)"]
      {@comb_b, [a, b, c]} -> [lam3(arena, a, b, c), "(X @ (Y @ Z)))"]
      {@comb_c, [a, b, c]} -> [lam3(arena, a, b, c), "((X @ Z) @ Y))"]
      {@comb_s, [a, b, c]} -> [lam3(arena, a, b, c), "((X @ Z) @ (Y @ Z)))"]
    end
  end

  defp lam3(arena, a, b, c) do
    ["(^ [X: ", type(arena, a), ", Y: ", type(arena, b), ", Z: ", type(arena, c), "]: "]
  end

  defp comb_arity(@comb_i), do: 1
  defp comb_arity(@comb_k), do: 2
  defp comb_arity(_), do: 3

  defp domains(_arena, _ty, 0), do: []

  defp domains(arena, ty, n) do
    {:arrow, dom, cod} = Map.fetch!(arena.type_table, ty)
    [dom | domains(arena, cod, n - 1)]
  end

  defp type_decls(arena, prefix) do
    arena.type_table
    |> Enum.flat_map(fn
      {_id, {:base, name}} -> [name]
      _ -> []
    end)
    |> Enum.sort()
    |> Enum.with_index()
    |> Enum.map(fn {name, idx} ->
      ["thf(", prefix, "ty_", Integer.to_string(idx), ", type, ", atom(name), ": $tType).\n"]
    end)
  end

  defp symbol_decls(arena, symbols, prefix) do
    symbols
    |> Enum.sort()
    |> Enum.with_index()
    |> Enum.map(fn {{name, ty}, idx} ->
      [
        ["thf(", prefix, "sym_", Integer.to_string(idx), ", type, ", atom(name), ": "],
        [type(arena, ty), ").\n"]
      ]
    end)
  end

  defp skolem_name(hash) do
    "sk_" <> String.downcase(String.pad_leading(Integer.to_string(hash, 16), 8, "0"))
  end
end
